#!/usr/bin/env python3
"""Underline all headline paragraphs in unpacked/word/document.xml (stdlib only)."""
import xml.dom.minidom as minidom
from pathlib import Path

doc_path = Path("unpacked/word/document.xml")
dom = minidom.parse(str(doc_path))

# Schema order of w:rPr children (CT_RPr) - w:u must be placed after w:highlight
RPR_ORDER = [
    "w:rStyle", "w:rFonts", "w:b", "w:bCs", "w:i", "w:iCs", "w:caps",
    "w:smallCaps", "w:strike", "w:dstrike", "w:outline", "w:shadow",
    "w:emboss", "w:imprint", "w:noProof", "w:snapToGrid", "w:vanish",
    "w:webHidden", "w:color", "w:spacing", "w:w", "w:kern", "w:position",
    "w:sz", "w:szCs", "w:highlight", "w:u", "w:effect", "w:bdr", "w:shd",
    "w:fitText", "w:vertAlign", "w:rtl", "w:cs", "w:em", "w:lang",
    "w:eastAsianLayout", "w:specVanish", "w:oMath",
]

W_NS = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"


def para_text(p):
    parts = []
    for t in p.getElementsByTagName("w:t"):
        if t.firstChild and t.firstChild.nodeType == t.TEXT_NODE:
            parts.append(t.firstChild.data)
    return "".join(parts)


def is_headline(text):
    """All-caps section headline: uppercase letters, no lowercase, not a divider line."""
    t = text.strip()
    if not t:
        return False
    has_upper = any(c.isascii() and c.isupper() for c in t)
    has_lower = any(c.isascii() and c.islower() for c in t)
    return has_upper and not has_lower


def add_underline(run):
    rprs = run.getElementsByTagName("w:rPr")
    if rprs:
        rpr = rprs[0]
    else:
        rpr = dom.createElementNS(W_NS, "w:rPr")
        run.insertBefore(rpr, run.firstChild)
    if rpr.getElementsByTagName("w:u"):
        return  # already underlined
    u = dom.createElementNS(W_NS, "w:u")
    u.setAttributeNS(W_NS, "w:val", "single")
    # Insert at schema-correct position (after w:highlight, before w:effect)
    children = [c for c in rpr.childNodes if c.nodeType == c.ELEMENT_NODE]
    insert_idx = len(children)
    for idx, child in enumerate(children):
        if child.tagName in RPR_ORDER and RPR_ORDER.index(child.tagName) > RPR_ORDER.index("w:u"):
            insert_idx = idx
            break
    if insert_idx < len(children):
        rpr.insertBefore(u, children[insert_idx])
    else:
        rpr.appendChild(u)


modified = []
for p in dom.getElementsByTagName("w:p"):
    text = para_text(p)
    if is_headline(text):
        for r in p.getElementsByTagName("w:r"):
            add_underline(r)
        modified.append(text.strip())

print(f"Underlined {len(modified)} headline(s):")
for m in modified:
    print(f"  - {m}")

with open(doc_path, "wb") as f:
    f.write(dom.toxml(encoding="UTF-8"))
print("Saved", doc_path)

